/* Dictionary for one language: English => translation (plus the Arabic source texts of the car editor). */
function orego_admin_dict( $lang ) {
	static $cache = array();
	if ( isset( $cache[ $lang ] ) ) {
		return $cache[ $lang ];
	}
	$i = array_search( $lang, orego_admin_dict_langs(), true );
	$d = array();
	if ( false !== $i ) {
		foreach ( orego_admin_dict_raw() as $en => $t ) {
			$d[ $en ] = $t[ $i ];
		}
		// The car editor boxes are written in Arabic: Arabic -> English -> this language.
		if ( function_exists( 'orego_i18n_ar2en' ) ) {
			foreach ( orego_i18n_ar2en() as $ar => $en ) {
				$d[ $ar ] = $d[ $en ] ?? $en;
			}
		}
	}
	return $cache[ $lang ] = $d;
}
